def patterns():
    rows=[]
    for line in PATTERN_ROWS.splitlines():
        key,title,priority,targets,action,assets,constraint,acceptance,status=line.split("|")
        rows.append(dict(id=key,title=title,priority=priority,targets=targets.split(","),
                         action=action,asset_briefs=assets.split(","),constraint=constraint,
                         acceptance=acceptance,project_status=status,decision_status="분석 및 적용 제안"))
    return rows


def assets():
    rows=[]
    for line in ASSET_ROWS.splitlines():
        key,title,kind,brief,status,constraint=line.split("|")
        rows.append(dict(id=key,title=title,kind=kind,brief=brief,project_status=status,constraint=constraint))
    return rows
